macro_rules! deps {
    () => {
        ReadBuf!();
    };
}

macro_rules! AsyncRead {
    () => {
        deps!();
        # [doc = " Reads bytes from a source."] # [doc = ""] # [doc = " This trait is analogous to the [`std::io::Read`] trait, but integrates with"] # [doc = " the asynchronous task system. In particular, the [`poll_read`] method,"] # [doc = " unlike [`Read::read`], will automatically queue the current task for wakeup"] # [doc = " and return if data is not yet available, rather than blocking the calling"] # [doc = " thread."] # [doc = ""] # [doc = " Specifically, this means that the `poll_read` function will return one of"] # [doc = " the following:"] # [doc = ""] # [doc = " * `Poll::Ready(Ok(()))` means that data was immediately read and placed into"] # [doc = "   the output buffer. The amount of data read can be determined by the"] # [doc = "   increase in the length of the slice returned by `ReadBuf::filled`. If the"] # [doc = "   difference is 0, either EOF has been reached, or the output buffer had zero"] # [doc = "   capacity (i.e. `buf.remaining()` == 0)."] # [doc = ""] # [doc = " * `Poll::Pending` means that no data was read into the buffer"] # [doc = "   provided. The I/O object is not currently readable but may become readable"] # [doc = "   in the future. Most importantly, **the current future's task is scheduled"] # [doc = "   to get unparked when the object is readable**. This means that like"] # [doc = "   `Future::poll` you'll receive a notification when the I/O object is"] # [doc = "   readable again."] # [doc = ""] # [doc = " * `Poll::Ready(Err(e))` for other errors are standard I/O errors coming from the"] # [doc = "   underlying object."] # [doc = ""] # [doc = " This trait importantly means that the `read` method only works in the"] # [doc = " context of a future's task. The object may panic if used outside of a task."] # [doc = ""] # [doc = " Utilities for working with `AsyncRead` values are provided by"] # [doc = " [`AsyncReadExt`]."] # [doc = ""] # [doc = " [`poll_read`]: AsyncRead::poll_read"] # [doc = " [`std::io::Read`]: std::io::Read"] # [doc = " [`Read::read`]: std::io::Read::read"] # [doc = " [`AsyncReadExt`]: crate::io::AsyncReadExt"] pub trait AsyncRead { # [doc = " Attempts to read from the `AsyncRead` into `buf`."] # [doc = ""] # [doc = " On success, returns `Poll::Ready(Ok(()))` and places data in the"] # [doc = " unfilled portion of `buf`. If no data was read (`buf.filled().len()` is"] # [doc = " unchanged), it implies that EOF has been reached, or the output buffer"] # [doc = " had zero capacity (i.e. `buf.remaining()` == 0)."] # [doc = ""] # [doc = " If no data is available for reading, the method returns `Poll::Pending`"] # [doc = " and arranges for the current task (via `cx.waker()`) to receive a"] # [doc = " notification when the object becomes readable or is closed."] fn poll_read (self : Pin < & mut Self > , cx : & mut Context < '_ > , buf : & mut ReadBuf < '_ > ,) -> Poll < io :: Result < () > > ; }
    };
}

AsyncRead!()